diff -ruN '--exclude=node_modules' '--exclude=.git' a/cron.rules.test.ts b/cron.rules.test.ts
--- a/cron.rules.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/cron.rules.test.ts	2026-10-29 18:47:10.363549346 +0000
@@ -0,0 +1,180 @@
+import { expect, test } from "bun:test";
+import { nextRun } from "./cron";
+
+const at = (iso: string) => new Date(iso);
+
+const seq = (expr: string, after: string, n: number): string[] => {
+  const out: string[] = [];
+  let d = at(after);
+  for (let i = 0; i < n; i++) {
+    d = nextRun(expr, d);
+    out.push(d.toISOString());
+  }
+  return out;
+};
+
+test("invalid expressions throw", () => {
+  const bad = [
+    "", "* * * * * *", "60 * * * *", "* 24 * * *", "* * 0 * *", "* * 32 * *", "* * * 0 *", "* * * 13 *",
+    "* * * * 8", "*/0 * * * *", "*/ * * * *", "*/x * * * *", "1/2/3 * * * *", "5-1 * * * *", "1,,2 * * * *",
+    "1.5 * * * *", "1-2-3 * * * *", "-1 * * * *", "1- * * * *", "* * * FOO *", "* * * MON *", "* * * * JAN",
+  ];
+  for (const expr of bad) expect(() => nextRun(expr, at("2026-01-01T00:00:00Z"))).toThrow(RangeError);
+});
+
+test("names are case insensitive", () => {
+  expect(seq("0 0 1 jan *", "2026-01-01T00:00:00Z", 2)).toEqual(seq("0 0 1 1 *", "2026-01-01T00:00:00Z", 2));
+  expect(seq("0 0 * * MON-fri", "2026-01-01T00:00:00Z", 5)).toEqual(seq("0 0 * * 1-5", "2026-01-01T00:00:00Z", 5));
+  expect(nextRun("0 0 * * sun", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-04T00:00:00.000Z");
+});
+
+test("a step from a value runs to the end of the field", () => {
+  expect(seq("5/20 * * * *", "2026-01-01T00:00:00Z", 4)).toEqual([
+    "2026-01-01T00:05:00.000Z", "2026-01-01T00:25:00.000Z", "2026-01-01T00:45:00.000Z", "2026-01-01T01:05:00.000Z",
+  ]);
+});
+
+test("a range or star with a step", () => {
+  expect(seq("10-30/10 * * * *", "2026-01-01T00:00:00Z", 4)).toEqual([
+    "2026-01-01T00:10:00.000Z", "2026-01-01T00:20:00.000Z", "2026-01-01T00:30:00.000Z", "2026-01-01T01:10:00.000Z",
+  ]);
+  expect(seq("*/15 * * * *", "2026-01-01T00:00:00Z", 4)).toEqual([
+    "2026-01-01T00:15:00.000Z", "2026-01-01T00:30:00.000Z", "2026-01-01T00:45:00.000Z", "2026-01-01T01:00:00.000Z",
+  ]);
+});
+
+test("Sunday is 0 or 7", () => {
+  expect(nextRun("0 0 * * 7", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-04T00:00:00.000Z");
+  expect(nextRun("0 0 * * 0", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-01-04T00:00:00.000Z");
+  expect(seq("0 0 * * 5-7", "2026-01-01T00:00:00Z", 3)).toEqual([
+    "2026-01-02T00:00:00.000Z", "2026-01-03T00:00:00.000Z", "2026-01-04T00:00:00.000Z",
+  ]);
+});
+
+test("day of month or day of week when both are restricted", () => {
+  expect(seq("0 0 1,15 * 1", "2026-01-01T00:00:00Z", 4)).toEqual([
+    "2026-01-05T00:00:00.000Z", "2026-01-12T00:00:00.000Z", "2026-01-15T00:00:00.000Z", "2026-01-19T00:00:00.000Z",
+  ]);
+});
+
+test("a full day field leaves the other field to decide", () => {
+  expect(seq("0 0 13 * 0-6", "2026-01-01T00:00:00Z", 2)).toEqual(["2026-01-13T00:00:00.000Z", "2026-02-13T00:00:00.000Z"]);
+  expect(seq("0 0 1-31 * 5", "2026-01-01T00:00:00Z", 2)).toEqual(["2026-01-02T00:00:00.000Z", "2026-01-09T00:00:00.000Z"]);
+});
+
+test("February 29 comes in leap years, even 8 years apart", () => {
+  expect(nextRun("0 0 29 2 *", at("2026-03-01T00:00:00Z")).toISOString()).toBe("2028-02-29T00:00:00.000Z");
+  expect(nextRun("0 0 29 2 *", at("2096-03-01T00:00:00Z")).toISOString()).toBe("2104-02-29T00:00:00.000Z");
+});
+
+test("an expression that never fires throws", () => {
+  expect(() => nextRun("0 0 30 2 *", at("2026-01-01T00:00:00Z"))).toThrow(RangeError);
+  expect(() => nextRun("0 0 31 4,6 *", at("2026-01-01T00:00:00Z"))).toThrow(RangeError);
+  expect(nextRun("0 0 30 2 1", at("2026-01-01T00:00:00Z")).toISOString()).toBe("2026-02-02T00:00:00.000Z");
+});
+
+test("fires strictly after, on a whole minute", () => {
+  expect(nextRun("* * * * *", at("2026-01-01T00:00:30Z")).toISOString()).toBe("2026-01-01T00:01:00.000Z");
+  expect(nextRun("5 0 * * *", at("2026-01-01T00:05:00Z")).toISOString()).toBe("2026-01-02T00:05:00.000Z");
+});
+
+const MONTH_NAMES = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
+const DAY_NAMES = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"];
+const RANGES: [number, number][] = [[0, 59], [0, 23], [1, 31], [1, 12], [0, 7]];
+
+function lcg(seed: number): () => number {
+  return () => {
+    seed = (Math.imul(seed, 1103515245) + 12345) & 0x7fffffff;
+    return seed / 0x80000000;
+  };
+}
+
+// A random field as its text, and the values it stands for (7 counted as 0).
+function randomField(rnd: () => number, i: number): { text: string; values: Set<number> } {
+  const [min, max] = RANGES[i]!;
+  const int = (lo: number, hi: number) => lo + Math.floor(rnd() * (hi - lo + 1));
+  const text = (v: number) => {
+    if (i === 3 && rnd() < 0.5) return MONTH_NAMES[v - 1]!;
+    if (i === 4 && v < 7 && rnd() < 0.5) return DAY_NAMES[v]!;
+    return String(v);
+  };
+  const values = new Set<number>();
+  const items: string[] = [];
+  for (let k = int(1, 2); k > 0; k--) {
+    const a = int(min, max);
+    const b = int(a, max);
+    const s = int(1, 5);
+    let item: string;
+    let lo = a;
+    let hi = b;
+    let step = 1;
+    switch (int(0, 5)) {
+      case 0: item = "*"; lo = min; hi = max; break;
+      case 1: item = text(a); hi = a; break;
+      case 2: item = `${text(a)}-${text(b)}`; break;
+      case 3: item = `${text(a)}/${s}`; hi = max; step = s; break;
+      case 4: item = `${text(a)}-${text(b)}/${s}`; step = s; break;
+      default: item = `*/${s}`; lo = min; hi = max; step = s; break;
+    }
+    for (let v = lo; v <= hi; v += step) values.add(v);
+    items.push(item);
+  }
+  if (values.has(7)) {
+    values.delete(7);
+    values.add(0);
+  }
+  return { text: items.join(","), values };
+}
+
+type Sets = Set<number>[];
+
+// The day rule of the doc comment, on value sets.
+function dayMatches(sets: Sets, d: Date): boolean {
+  const doms = sets[2]!;
+  const dows = sets[4]!;
+  const dom = doms.has(d.getUTCDate());
+  const dow = dows.has(d.getUTCDay());
+  const day = doms.size === 31 || dows.size === 7 ? dom && dow : dom || dow;
+  return sets[3]!.has(d.getUTCMonth() + 1) && day;
+}
+
+function fires(sets: Sets, d: Date): boolean {
+  return dayMatches(sets, d) && sets[1]!.has(d.getUTCHours()) && sets[0]!.has(d.getUTCMinutes());
+}
+
+// Whether some whole minute strictly between after and before fires, checked minute by minute.
+function firesBetween(sets: Sets, after: Date, before: Date): boolean {
+  let t = Math.floor(after.getTime() / 60_000) * 60_000 + 60_000;
+  while (t < before.getTime()) {
+    const d = new Date(t);
+    if (!dayMatches(sets, d)) t = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate() + 1);
+    else {
+      if (fires(sets, d)) return true;
+      t += 60_000;
+    }
+  }
+  return false;
+}
+
+test("agrees with a brute-force reference on random expressions", () => {
+  const rnd = lcg(42);
+  let checked = 0;
+  for (let n = 0; n < 200; n++) {
+    const fields = [0, 1, 2, 3, 4].map((i) => randomField(rnd, i));
+    const expr = fields.map((f) => f.text).join(" ");
+    const sets = fields.map((f) => f.values);
+    for (let k = 0; k < 3; k++) {
+      const after = new Date(Date.UTC(2026, 0, 1) + Math.floor(rnd() * 2 * 365 * 24 * 3600_000));
+      let next: Date;
+      try {
+        next = nextRun(expr, after);
+      } catch (e) {
+        if (e instanceof RangeError && e.message.endsWith("never fires")) continue;
+        throw e;
+      }
+      checked++;
+      expect({ expr, fires: fires(sets, next), earlier: firesBetween(sets, after, next) }).toEqual({ expr, fires: true, earlier: false });
+    }
+  }
+  expect(checked).toBeGreaterThan(300);
+});
